from transformers import GPTJForCausalLM, GPTJConfig

def load_model():
    return GPTJForCausalLM.from_pretrained("EleutherAI/gpt-j-6B")

def generate_prompt(model, prompt):
    tokens = model.tokenizer.encode(prompt)
    generated = model.generate(tokens, max_length=50, do_sample=True, temperature=0.7)
    return model.tokenizer.decode(generated[0])

def main():
    model = load_model()
    prompt = "What does 'defund the police' mean?"
    print(generate_prompt(model, prompt))

if __name__ == "__main__":
    main()

