from PIL import Image
import glob

def crop(image_path):
    with Image.open(image_path) as img:
        w, h = img.size
        cropped = img.crop((50, 50, w, h))

        if img.format == "JPEG":
            cropped.save(image_path + "_cropped")
        else:
            cropped.save(image_path + "_cropped")

for image_path in glob.glob("*.jpg"):
    crop(image_path)

