import math

def sum_of_digits(num):
    total = 0
    for digit in str(num):
        total += int(digit)
    return total

def average_family_size(size):
    if size == 0:
        return 0
    factors = []
    for i in range(1, int(math.sqrt(size)) + 1):
        if size % i == 0:
            factors.append(i)
            if i != size // i:
                factors.append(size // i)

    family_size = sum(factors) / len(factors)

    return family_size

size = 1000000000000000000000
print(average_family_size(size))

